def solve_max_L(C, steps=1000):
    L = 0.0
    delta = 0.0
    for _ in range(steps):
        best_L_next = -1.0
        best_delta_next = 0.0
        # The adversary wants to choose c < C to maximize the resulting L.
        # Let's try a more exhaustive search for c.
        for c in [C * 0.99, C * 0.98, C * 0.97, C * 0.96, C * 0.95, C * 0.94, C * 0.93, C * 0.92, C * 0.91, C * 0.90]:
            L1 = max(L, delta + c)
            delta1 = delta + c
            L2 = max(L, L - delta + c)
            delta2 = max(0, delta - c)

            if L1 < L2:
                curr_L, curr_delta = L1, delta1
            elif L2 < L1:
                curr_L, curr_delta = L2, delta2
            else:
                if abs(delta1 - L1/2) < abs(delta2 - L2/2):
                    curr_L, curr_delta = L1, delta1
                else:
                    curr_L, curr_delta = L2, delta2

            if curr_L > best_L_next:
                best_L_next = curr_L
                best_delta_next = curr_delta

        L = best_L_next
        delta = best_delta_next
        if L >= 1.0:
            return L
    return L

for C in [0.5, 0.6, 0.7, 0.8, 0.9, 1.0]:
    print(f"C={C}: max_L={solve_max_L(C)}")
